def fill(G):
    h,w=len(G),len(G[0])
    from collections import defaultdict
    vals=defaultdict(set)
    for i in range(h):
        for j in range(w):
            if G[i][j]!=0: vals[i+j].add(G[i][j])
    out=[row[:] for row in G]
    for i in range(h):
        for j in range(w):
            if out[i][j]==0:
                s=vals.get(i+j)
                if not s or len(s)!=1: return None,(i,j,s)
                out[i][j]=next(iter(s))
    return out,None
